/**
 * Unified Ticker Fallback System
 *
 * Auto-generated by update-ticker-fallback.mjs on 2026-08-12 09:53:42
 * Contains historical daily close prices for 88 tickers.
 *
 * Format: Columnar (highly compressible) with integer encoding
 * - Dates as YYYYMMDD integers (e.g., 20260105 = January 5, 2026)
 * - Closes as integers ×100 (e.g., 15099 = $150.99)
 */

// ============================================================================
// INTERFACES & TYPES
// ============================================================================

export interface StockDataPoint {
	date: string; // ISO format: YYYY-MM-DD
	adjClose: number; // Adjusted close price
}

export interface CachedStockData {
	symbol: string;
	shortName: string;
	regularMarketPrice: number;
	currency: string;
	history: StockDataPoint[];
}

export interface Top100TickerData {
	symbol: string;
	name: string;
	currency: string;
	dates: number[]; // YYYYMMDD format (e.g., 20260105)
	closes: number[]; // Close price × 100 (e.g., 15099 = $150.99)
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Extract a single ticker's data from the columnar format
 */
export function getTop100TickerData(symbol: string): Top100TickerData | null {
	const tickers = getAllTickersData();
	const ticker = tickers.find((t: Top100TickerData) => t.symbol === symbol.toUpperCase());
	if (!ticker) return null;

	return {
		symbol: ticker.symbol,
		name: ticker.name,
		currency: ticker.currency,
		dates: ticker.dates,
		closes: ticker.closes
	};
}

/**
 * Convert columnar data to StockDataPoint array for compatibility
 */
export function convertTop100ToHistory(data: Top100TickerData): StockDataPoint[] {
	return data.dates.map((dateNum, idx) => {
		const dateStr = dateNum.toString();
		const year = dateStr.slice(0, 4);
		const month = dateStr.slice(4, 6);
		const day = dateStr.slice(6, 8);
		const date = `${year}-${month}-${day}`;
		const adjClose = data.closes[idx] / 100; // Convert from integer back to decimal
		return { date, adjClose };
	});
}

/**
 * Get the most recent price for a ticker
 */
export function getLatestPrice(symbol: string): number | null {
	const data = getTop100TickerData(symbol);
	if (!data || data.closes.length === 0) return null;
	return data.closes[data.closes.length - 1] / 100;
}

