/**
 * Get fallback data for a ticker symbol (returns null if not found)
 */
export function getStaticFallbackData(symbol: string): CachedStockData | null {
	const data = getTop100TickerData(symbol);
	if (!data) return null;
	return {
		symbol: data.symbol,
		shortName: data.name,
		regularMarketPrice: data.closes[data.closes.length - 1] / 100,
		currency: data.currency,
		history: convertTop100ToHistory(data)
	};
}

